const incomingItems = $input.all();
const validRecords = [];
const rejectedRecords = [];

// Calculate summary stats across all items
let totalProcessed = incomingItems.length;
let totalValid = 0;
let totalRejected = 0;

for (let i = 0; i < incomingItems.length; i++) {
  const rawRow = incomingItems[i].json;

  // Normalize row keys to lowercase to eliminate header case mismatches
  const row = {};
  for (const key in rawRow) {
    row[key.toLowerCase().trim()] = rawRow[key];
  }

  let rejectionReasons = [];

  // Extract fields flexibly regardless of CSV casing
  const dateVal = row.date;
  const regionVal = row.region;
  const categoryVal = row.category;
  const productVal = row.product;
  const salesVal = row.sales;
  const profitVal = row.profit;
  const quantityVal = row.quantity;

  // 1. Column Presence Check
  if (salesVal === undefined) rejectionReasons.push("Missing Sales field");
  if (profitVal === undefined) rejectionReasons.push("Missing Profit field");
  if (quantityVal === undefined) rejectionReasons.push("Missing Quantity field");

  // 2. Data Type Validation
  const salesNum = Number(salesVal);
  const profitNum = Number(profitVal);
  const qtyNum = Number(quantityVal);

  if (isNaN(salesNum)) rejectionReasons.push("Invalid Sales value");
  if (isNaN(profitNum)) rejectionReasons.push("Invalid Profit value");
  if (isNaN(qtyNum)) rejectionReasons.push("Invalid Quantity value");

  // Format valid record (match exact NocoDB schema casing)
  if (rejectionReasons.length === 0) {
    totalValid++;
    validRecords.push({
      json: {
        Date: dateVal ? String(dateVal).trim() : new Date().toISOString().split('T')[0],
        Region: regionVal ? String(regionVal).trim() : "Unknown",
        Category: categoryVal ? String(categoryVal).trim() : "General",
        Product: productVal ? String(productVal).trim() : "Item",
        Sales: salesNum,
        Profit: profitNum,
        Quantity: qtyNum
      }
    });
  } else {
    totalRejected++;
    rejectedRecords.push({
      row_number: i + 1,
      reasons: rejectionReasons.join("; ")
    });
  }
}

// Attach metadata summary to items so reporter node receives it downstream
return validRecords.map((rec, index) => ({
  json: {
    ...rec.json,
    _summary: {
      total_processed: totalProcessed,
      total_valid: totalValid,
      total_rejected: totalRejected,
      rejected_details: rejectedRecords
    }
  }
}));

const items = $input.all();
const summaryData = items[0]?.json?._summary || {
  total_processed: items.length,
  total_valid: items.length,
  total_rejected: 0,
  rejected_details: []
};

const outputReport = `
# Data Ingestion Execution Summary Report

## Overview
- **Total Records Received:** ${summaryData.total_processed}
- **Successfully Ingested into NocoDB:** ${summaryData.total_valid}
- **Rejected Records:** ${summaryData.total_rejected}

## Status
${summaryData.total_rejected === 0 ? "✅ **SUCCESS:** All incoming records passed validation and were successfully loaded into NocoDB." : "⚠️ **COMPLETED WITH WARNINGS:** Some records were rejected due to schema or validation errors."}

## Rejected Records Log
${summaryData.rejected_details.length > 0 ? summaryData.rejected_details.map(r => `- **Row ${r.row_number}:**${r.reasons}`).join("\n") : "*No records were rejected.*"}
`;

return { json: { report: outputReport } };
